var docs = new List<object>();
foreach (Document d in app.Documents) docs.Add(new { d.Title, d.PathName, d.IsLinked, d.IsFamilyDocument });
var sel = uidoc.Selection.GetElementIds().Select(id => { var e = doc.GetElement(id); return new { id = id.IntegerValue, cat = e?.Category?.Name, name = e?.Name, cls = e?.GetType().Name }; }).ToList();
var kw = Tama.Args.Get(args, "keyword", "").ToUpper();
var schedules = new FilteredElementCollector(doc).OfClass(typeof(ViewSchedule)).Cast<ViewSchedule>()
  .Where(v => !v.IsTemplate && !v.IsTitleblockRevisionSchedule && !v.IsInternalKeynoteSchedule)
  .Where(v => v.Name.ToUpper().Contains(kw))
  .Select(v => new { id = v.Id.IntegerValue, v.Name, cat = v.Definition.CategoryId.IntegerValue, isKey = v.Definition.IsKeySchedule }).ToList();
return new { docs, sel, schedules };
